import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, utimesSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterEach, describe, expect, it } from 'vitest';
import type { TypingsUpdate } from '../bundler/featureApi/index.js';
import type { Logger } from '../shared/logger.js';
import { createAssetTypings } from './assetTypings.js';

const workspace = fileURLToPath(new URL('../../node_modules/.cache/fast-serve-tests/', import.meta.url));

const heftAssetTypings =
  '// This file was generated by a tool. Modifying it will produce unexpected behavior\n\n/**\n * @public\n */\ndeclare const content: string;\nexport default content;\n';

const roots: string[] = [];

afterEach(() => {
  for (const root of roots.splice(0)) rmSync(root, { recursive: true, force: true });
});

function project(files: Record<string, string>): string {
  mkdirSync(workspace, { recursive: true });
  const root = mkdtempSync(path.join(workspace, 'asset-typings-'));
  roots.push(root);
  for (const [file, content] of Object.entries({ 'package.json': '{ "name": "assets-fixture", "version": "1.0.0" }', ...files })) {
    mkdirSync(path.dirname(path.join(root, file)), { recursive: true });
    writeFileSync(path.join(root, file), content);
  }
  return root;
}

function recordingLogger(): Logger & { messages: string[] } {
  const messages: string[] = [];
  const record = (message: string) => {
    messages.push(message);
  };
  return { messages, info: record, warn: record, error: record };
}

const typingsOf = (root: string, asset: string) => path.join(root, 'temp/static-asset-ts', `${asset}.d.ts`);

const spfxRigConfig = {
  'config/static-asset-typings-base.json': JSON.stringify({ generatedTsFolders: ['temp/static-asset-ts'], fileExtensions: ['.png', '.svg'] }),
  'config/static-asset-typings.json': JSON.stringify({ extends: './static-asset-typings-base.json', fileExtensions: ['.webp'] }),
};

describe('static asset typings', () => {
  it('writes heft-identical typings for every asset under src, with inherited extensions appended', async () => {
    const root = project({
      ...spfxRigConfig,
      'src/webparts/hello/assets/logo.png': 'png',
      'src/webparts/hello/assets/icon.svg': '<svg/>',
      'src/webparts/hello/assets/photo.webp': 'webp',
      'src/webparts/hello/assets/notes.txt': 'text',
    });
    const logger = recordingLogger();
    await createAssetTypings({ root, logger }).generateAll();
    for (const asset of ['logo.png', 'icon.svg', 'photo.webp']) {
      expect(readFileSync(typingsOf(root, `webparts/hello/assets/${asset}`), 'utf8')).toBe(heftAssetTypings);
    }
    expect(existsSync(typingsOf(root, 'webparts/hello/assets/notes.txt'))).toBe(false);
    expect(logger.messages).toEqual([]);
  });

  it('adds typings for new assets and removes them with the asset', async () => {
    const root = project(spfxRigConfig);
    const typings = createAssetTypings({ root, logger: recordingLogger() });
    await typings.generateAll();
    const asset = path.join(root, 'src/components/new.png');
    mkdirSync(path.dirname(asset), { recursive: true });
    writeFileSync(asset, 'png');
    await typings.fileAdded(asset);
    expect(readFileSync(typingsOf(root, 'components/new.png'), 'utf8')).toBe(heftAssetTypings);
    rmSync(asset);
    await typings.fileRemoved(asset);
    expect(existsSync(typingsOf(root, 'components/new.png'))).toBe(false);
  });

  it('ignores files outside src and other extensions', async () => {
    const root = project(spfxRigConfig);
    const typings = createAssetTypings({ root, logger: recordingLogger() });
    await typings.fileAdded(path.join(root, 'lib/components/logo.png'));
    await typings.fileAdded(path.join(root, 'src/components/Card.tsx'));
    expect(existsSync(path.join(root, 'temp'))).toBe(false);
  });

  it('does nothing without a static asset typings configuration', async () => {
    const root = project({ 'src/logo.png': 'png' });
    const logger = recordingLogger();
    await createAssetTypings({ root, logger }).generateAll();
    expect(existsSync(path.join(root, 'temp'))).toBe(false);
    expect(logger.messages).toEqual([]);
  });

  it('warns once when the configuration is invalid', async () => {
    const root = project({ 'config/static-asset-typings.json': JSON.stringify({ fileExtensions: 'png' }), 'src/logo.png': 'png' });
    const logger = recordingLogger();
    const typings = createAssetTypings({ root, logger });
    await typings.generateAll();
    await typings.fileAdded(path.join(root, 'src/logo.png'));
    expect(logger.messages).toHaveLength(1);
    expect(logger.messages[0]).toMatch(/^Static asset typings are not generated: .*static-asset-typings\.json/s);
    expect(existsSync(path.join(root, 'temp'))).toBe(false);
  });

  it('keeps unchanged typings untouched across restarts and reports only the typings it writes or removes', async () => {
    const root = project({ ...spfxRigConfig, 'src/logo.png': 'png', 'src/icon.svg': '<svg/>' });
    const firstUpdates: TypingsUpdate[] = [];
    await createAssetTypings({ root, logger: recordingLogger(), onTypingsUpdated: (update) => firstUpdates.push(update) }).generateAll();
    expect(firstUpdates.flatMap(({ written }) => written).toSorted()).toEqual([typingsOf(root, 'icon.svg'), typingsOf(root, 'logo.png')]);

    const past = new Date('2020-01-01T00:00:00Z');
    utimesSync(typingsOf(root, 'logo.png'), past, past);
    rmSync(typingsOf(root, 'icon.svg'));
    const updates: TypingsUpdate[] = [];
    const typings = createAssetTypings({ root, logger: recordingLogger(), onTypingsUpdated: (update) => updates.push(update) });
    await typings.generateAll();
    await typings.fileAdded(path.join(root, 'src/logo.png'));
    rmSync(path.join(root, 'src/icon.svg'));
    await typings.fileRemoved(path.join(root, 'src/icon.svg'));

    expect(statSync(typingsOf(root, 'logo.png')).mtimeMs).toBe(past.getTime());
    expect(updates).toEqual([
      { written: [typingsOf(root, 'icon.svg')], removed: [] },
      { written: [], removed: [typingsOf(root, 'icon.svg')] },
    ]);
  });
});
